import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import path from 'node:path';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),React=require('react'),ts=require('typescript'),{renderToStaticMarkup}=require('react-dom/server');
const root=path.resolve(import.meta.dirname,'..');
const topics=[{id:'support',visible:true,title:'Profile help',body:'Help with a Profile',ctaUrl:'mailto:support@qrguitar.com?subject=Profile%20help',ctaLabel:'Ask about this Profile',icon:'HelpCircle'},{id:'info',visible:true,title:'Useful information',body:'Read this information',ctaUrl:'',ctaLabel:'Must not appear',icon:'Info'}];
async function render(file,collections=[]){const settings={content:{},composition:{contact:{sections:[{id:'hero',visible:true},{id:'categories',visible:true,blocks:topics},{id:'checklist',visible:true}]}}};const source=fs.readFileSync(path.join(root,file),'utf8');const m={exports:{}};const modules=key=>{if(key==='react')return React;const actualModules={'./ContactEmailDraft':'app/contact/ContactEmailDraft.tsx','../../lib/support-email-draft':'lib/support-email-draft.ts'};if(Object.hasOwn(actualModules,key)){const dependency={exports:{}};const actual=fs.readFileSync(path.join(root,actualModules[key]),'utf8');const compiled=ts.transpileModule(actual,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;new Function('require','exports','module',compiled)(modules,dependency.exports,dependency);if(key==='./ContactEmailDraft')assert.equal(typeof dependency.exports.ContactEmailDraft,'function');else assert.equal(typeof dependency.exports.buildSupportEmailDraft,'function');return dependency.exports;}if(key==='react/jsx-runtime')return require(key);if(key==='next/link')return {__esModule:true,default:'a'};if(key==='lucide-react')return {ArrowUpRight:()=>React.createElement('svg',{'aria-hidden':true})};if(key.endsWith('.module.css'))return {__esModule:true,default:new Proxy({},{get:(_,k)=>String(k)})};if(key.endsWith('/ui-text'))return {createUiText:()=>((key,fallback)=>fallback)};if(key.endsWith('/site-settings-server'))return {loadPublishedSiteSettings:async()=>settings};if(key.endsWith('/Nav'))return {Nav:()=>null};if(key.endsWith('/Footer'))return {Footer:()=>null};if(key.endsWith('/EditorialIcon'))return {EditorialIcon:()=>React.createElement('svg')};if(key.endsWith('/content-registry'))return {getContentValue:(_,key)=>key};if(key.endsWith('/site-metadata'))return {buildManagedPageMetadata:()=>({})};if(key.endsWith('/public-instruments'))return {getPublicInstruments:async()=>[]};if(key.endsWith('/collection-directory'))return {buildCollectionDirectory:()=>collections};if(key.endsWith('/seo'))return {buildCollectionsDirectoryJsonLd:()=>({}),serializeJsonLd:()=> '{}'};if(key.endsWith('/CollectionsDirectoryClient'))return {CollectionsDirectoryClient:()=>React.createElement('div',{'data-directory':true})};throw Error('Unexpected import '+key)};new Function('require','exports','module',ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText)(modules,m.exports,m);return renderToStaticMarkup(await m.exports.default());}
test('Actual contact page preserves support mailto subject and published CTA; informational topic has no link affordance',async()=>{const html=await render('app/contact/page.tsx');assert.match(html,/href="mailto:support@qrguitar.com\?subject=Profile%20help"/);assert.match(html,/Ask about this Profile/);assert.match(html,/<article[^>]*>[\s\S]*Useful information[\s\S]*<\/article>/);assert.doesNotMatch(html,/Must not appear/);});
test('Populated collection directory keeps one secondary setup destination after directory',async()=>{const html=await render('app/collections/page.tsx',[{handle:'fixture'}]);assert.equal((html.match(/href="\/account\?section=collection"/g)||[]).length,1);assert.ok(html.indexOf('data-directory')<html.indexOf('Collection settings'));assert.doesNotMatch(html,/Set up your collection/);});
test('Empty collection directory retains its existing client empty-state boundary without duplicate setup controls',async()=>{const html=await render('app/collections/page.tsx');assert.match(html,/data-directory/);assert.doesNotMatch(html,/Collection settings|Set up your collection/);});
